-- Local draft only. Version 0 means UNKNOWN, including all existing jobs.
-- The marker cannot be activated while the barrier exists. No reader may use
-- this counter to release a claim or infer provider quiescence.
ALTER TABLE sync_jobs ADD COLUMN serial_provenance_version INTEGER NOT NULL DEFAULT 0 CHECK(serial_provenance_version IN (0,1));
ALTER TABLE sync_jobs ADD COLUMN serial_lease_generation INTEGER NOT NULL DEFAULT 0 CHECK(serial_lease_generation BETWEEN 0 AND 2147483647);
CREATE TABLE IF NOT EXISTS serial_job_provenance_activation(singleton INTEGER PRIMARY KEY CHECK(singleton=1),spreadsheet_id TEXT NOT NULL CHECK(length(spreadsheet_id) BETWEEN 1 AND 256),activated_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS serial_job_provenance_not_ready BEFORE INSERT ON serial_job_provenance_activation BEGIN SELECT RAISE(ABORT,'job provenance not ready'); END;
-- Prevent out-of-order activation: the independently gated source marker and
-- its complete guard set must exist for the same workbook first. Trigger names
-- alone do not authenticate DDL and are not a release proof.
CREATE TRIGGER IF NOT EXISTS serial_job_provenance_source_gate BEFORE INSERT ON serial_job_provenance_activation
WHEN (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_source_provenance_no_update','serial_source_provenance_no_delete','serial_source_provenance_no_replace','serial_source_provenance_namespace_guard','serial_source_provenance_insert_guard','serial_source_provenance_update_guard','serial_source_provenance_delete_guard','serial_source_job_birth_guard'))<>8
 OR EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='serial_source_provenance_not_ready')
 OR NOT EXISTS(SELECT 1 FROM serial_source_provenance_activation WHERE singleton=1 AND spreadsheet_id=NEW.spreadsheet_id)
BEGIN SELECT RAISE(ABORT,'source provenance unavailable'); END;
CREATE TRIGGER IF NOT EXISTS serial_job_provenance_activation_no_update BEFORE UPDATE ON serial_job_provenance_activation BEGIN SELECT RAISE(ABORT,'activation immutable'); END;
CREATE TRIGGER IF NOT EXISTS serial_job_provenance_activation_no_delete BEFORE DELETE ON serial_job_provenance_activation BEGIN SELECT RAISE(ABORT,'activation retained'); END;
CREATE TRIGGER IF NOT EXISTS serial_job_provenance_activation_no_replace BEFORE INSERT ON serial_job_provenance_activation WHEN EXISTS(SELECT 1 FROM serial_job_provenance_activation WHERE singleton=NEW.singleton OR rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'activation collision'); END;
CREATE TRIGGER IF NOT EXISTS serial_job_provenance_insert_guard BEFORE INSERT ON sync_jobs
WHEN (NEW.serial_provenance_version=1 AND (NEW.entity_type<>'EXPENSE' OR NEW.entity_version<>1 OR EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='serial_source_provenance_not_ready') OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_source_provenance_no_update','serial_source_provenance_no_delete','serial_source_provenance_no_replace','serial_source_provenance_namespace_guard','serial_source_provenance_insert_guard','serial_source_provenance_update_guard','serial_source_provenance_delete_guard','serial_source_job_birth_guard'))<>8 OR NOT EXISTS(SELECT 1 FROM serial_job_provenance_activation a JOIN continuous_daily_post_cutover_expenses p ON p.spreadsheet_id=a.spreadsheet_id AND p.expense_id=NEW.entity_key JOIN continuous_daily_cutovers c ON c.spreadsheet_id=a.spreadsheet_id AND c.state='ACTIVE' JOIN expense_events e ON e.expense_id=p.expense_id AND e.version=NEW.entity_version AND e.status='CONFIRMED' WHERE a.singleton=1) OR EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='serial_job_provenance_not_ready') OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_job_provenance_insert_guard','serial_job_provenance_update_guard','serial_job_provenance_delete_guard','serial_job_provenance_activation_no_update','serial_job_provenance_activation_no_delete','serial_job_provenance_activation_no_replace','continuous_daily_post_no_delete','continuous_daily_post_no_update','continuous_daily_post_no_replace','continuous_daily_record_post_cutover'))<>10 OR NEW.status<>'PENDING' OR NEW.attempt_count<>0 OR NEW.lease_token IS NOT NULL OR NEW.lease_until IS NOT NULL OR NEW.serial_lease_generation<>0))
 OR (NEW.serial_provenance_version=0 AND NEW.serial_lease_generation<>0)
 OR (EXISTS(SELECT 1 FROM serial_job_provenance_activation WHERE singleton=1) AND EXISTS(SELECT 1 FROM sync_jobs j WHERE (j.serial_provenance_version=1 OR NEW.serial_provenance_version=1 OR EXISTS(SELECT 1 FROM serial_job_provenance_activation a JOIN continuous_daily_post_cutover_expenses p ON p.spreadsheet_id=a.spreadsheet_id WHERE a.singleton=1 AND ((j.entity_type='EXPENSE' AND p.expense_id=j.entity_key) OR (NEW.entity_type='EXPENSE' AND p.expense_id=NEW.entity_key)))) AND (j.job_id=NEW.job_id OR j.rowid=NEW.rowid OR (j.entity_type=NEW.entity_type AND j.entity_key=NEW.entity_key AND j.entity_version=NEW.entity_version))))
BEGIN SELECT RAISE(ABORT,'job provenance insert invalid'); END;
CREATE TRIGGER IF NOT EXISTS serial_job_provenance_update_guard BEFORE UPDATE ON sync_jobs
WHEN NEW.serial_provenance_version IS NOT OLD.serial_provenance_version
 OR ((OLD.serial_provenance_version=1 OR EXISTS(SELECT 1 FROM serial_job_provenance_activation a JOIN continuous_daily_post_cutover_expenses p ON p.spreadsheet_id=a.spreadsheet_id WHERE a.singleton=1 AND ((OLD.entity_type='EXPENSE' AND p.expense_id=OLD.entity_key) OR (NEW.entity_type='EXPENSE' AND p.expense_id=NEW.entity_key)))) AND (NEW.job_id IS NOT OLD.job_id OR NEW.entity_type IS NOT OLD.entity_type OR NEW.entity_key IS NOT OLD.entity_key OR NEW.entity_version IS NOT OLD.entity_version))
 OR (OLD.serial_provenance_version=0 AND NEW.serial_lease_generation<>0)
 OR (OLD.serial_provenance_version=1 AND (
   (NEW.status='PROCESSING' AND (OLD.status<>'PROCESSING' OR NEW.lease_token IS NOT OLD.lease_token OR NEW.lease_until IS NOT OLD.lease_until) AND NEW.serial_lease_generation<>OLD.serial_lease_generation+1)
   OR (NOT (NEW.status='PROCESSING' AND (OLD.status<>'PROCESSING' OR NEW.lease_token IS NOT OLD.lease_token OR NEW.lease_until IS NOT OLD.lease_until)) AND NEW.serial_lease_generation<>OLD.serial_lease_generation)))
BEGIN SELECT RAISE(ABORT,'job provenance update invalid'); END;
CREATE TRIGGER IF NOT EXISTS serial_job_provenance_delete_guard BEFORE DELETE ON sync_jobs WHEN OLD.serial_provenance_version=1 OR (OLD.entity_type='EXPENSE' AND EXISTS(SELECT 1 FROM serial_job_provenance_activation a JOIN continuous_daily_post_cutover_expenses p ON p.spreadsheet_id=a.spreadsheet_id WHERE a.singleton=1 AND p.expense_id=OLD.entity_key)) BEGIN SELECT RAISE(ABORT,'job provenance retained'); END;
